const output = $input.first().json.stdout;
const data = JSON.parse(output);

return {
  json: {
    hasUpdates: data.hasUpdates,
    totalUpdates: data.totalUpdates,
    updates: data.upgrades,
    projectPath: data.projectPath
  }
};

const output = $input.first().json.stdout;
const data = JSON.parse(output);

return {
  json: {
    status: data.status,
    hasErrors: data.hasErrors,
    installPassed: data.install.passed,
    installExitCode: data.install.exitCode,
    dependencyErrors: data.install.dependencyErrors,
    hasWarnings: data.hasWarnings || false,
    fullOutput: data.install.output
  }
};

// Prepare error context for Claude
const errors = $input.first().json.dependencyErrors;
const fullOutput = $input.first().json.fullOutput;

// Create a temporary file with the errors
const errorContext = `npm install failed with the following dependency conflicts:

${errors}

Full output:
${fullOutput}

Please analyze these dependency conflicts and provide fixes. Common solutions:
1. Use --legacy-peer-deps flag
2. Update conflicting peer dependencies
3. Add resolutions to package.json
4. Update package versions to compatible ranges
`;

return {
  json: {
    errorContext: errorContext,
    errors: errors
  }
};

const output = $input.first().json.stdout;
const data = JSON.parse(output);

return {
  json: {
    fixes: data.fixes || [],
    fixCount: (data.fixes || []).length,
    claudeAnalysis: data.analysis || 'No analysis provided'
  }
};

const output = $input.first().json.stdout;
const data = JSON.parse(output);

return {
  json: {
    installPassed: data.install.passed,
    message: data.install.passed ? 'npm install succeeded after fixes!' : 'npm install still failing',
    status: data.status
  }
};

const output = $input.first().json.stdout;
const data = JSON.parse(output);

return {
  json: {
    testPassed: data.test.passed,
    buildPassed: data.build.passed,
    summary: `Tests: ${data.test.passed ? 'PASSED ✓' : 'FAILED ✗'} | Build: ${data.build.passed ? 'PASSED ✓' : 'FAILED ✗'}`
  }
};

return {
  json: {
    message: "No updates available",
    totalUpdates: 0
  }
};

// Get branch name from earlier in workflow
const branchOutput = $('Create Test Branch').first().json.stdout;
const branchMatch = branchOutput.match(/Switched to a new branch '([^']+)'/);
let branchName = branchMatch ? branchMatch[1] : 'test-deps-update';

// If branch match failed, try to extract from stderr
if (!branchMatch) {
  const stderrOutput = $('Create Test Branch').first().json.stderr || '';
  const stderrMatch = stderrOutput.match(/Switched to a new branch '([^']+)'/);
  if (stderrMatch) {
    branchName = stderrMatch[1];
  }
}

// Get update info
const updateInfo = $('Parse Updates').first().json;
const testResults = $input.first().json;

// Build PR title
const title = `Update Angular Dependencies - ${updateInfo.totalUpdates} packages (${new Date().toISOString().split('T')[0]})`;

// Build PR body - handle updates array safely
let updateList = '';
if (updateInfo.updates && Array.isArray(updateInfo.updates) && updateInfo.updates.length > 0) {
  // Show first 10 updates, then indicate if there are more
  const displayUpdates = updateInfo.updates.slice(0, 10);
  updateList = displayUpdates.map(u =>
    `- **${u.name}**: ${u.from} → ${u.to}`
  ).join('\n');

  if (updateInfo.updates.length > 10) {
    updateList += `\n\n...and ${updateInfo.updates.length - 10} more packages`;
  }
} else {
  updateList = '_See commit for full list of dependency updates_';
}

const body = `## 📦 Dependency Updates

This PR updates ${updateInfo.totalUpdates} packages to their latest versions.

### Updates Applied
${updateList}

### Test Results
| Check | Status |
|-------|--------|
| **Tests** | ${testResults.testPassed ? '✅ PASSED' : '❌ FAILED'} |
| **Build** | ${testResults.buildPassed ? '✅ PASSED' : '❌ FAILED'} |

### Details
- **Branch**: \`${branchName}\`
- **Generated**: ${new Date().toISOString()}
- **Automated by**: n8n dependency update workflow

---
*This PR was automatically generated. Please review the changes before merging.*
`;

return {
  json: {
    title: title,
    body: body,
    branchName: branchName,
    updateCount: updateInfo.totalUpdates
  }
};

const output = $input.first().json.stdout;

try {
  const data = JSON.parse(output);

  return {
    json: {
      success: data.success,
      prExists: data.prExists || false,
      prNumber: data.pr ? data.pr.number : null,
      prUrl: data.pr ? data.pr.url : null,
      prState: data.pr ? data.pr.state : null,
      message: data.prExists ? 'PR already exists' : 'PR created successfully',
      repository: data.repository || {},
      timestamp: data.timestamp || new Date().toISOString()
    }
  };
} catch (e) {
  return {
    json: {
      success: false,
      error: 'Failed to parse PR response',
      rawOutput: output
    }
  };
}

// Prepare Confluence documentation data
const branchOutput = $('Create Test Branch').first().json.stdout;
const branchMatch = branchOutput.match(/Switched to a new branch '([^']+)'/);
let branchName = branchMatch ? branchMatch[1] : 'test-deps-update';

if (!branchMatch) {
  const stderrOutput = $('Create Test Branch').first().json.stderr || '';
  const stderrMatch = stderrOutput.match(/Switched to a new branch '([^']+)'/);
  if (stderrMatch) {
    branchName = stderrMatch[1];
  }
}

const updateInfo = $('Parse Updates').first().json;
const testResults = $('Parse Test Results').first().json;
const prResponse = $input.first().json;

// Get install results to check for errors OR warnings
let hasInstallErrors = false;
let hasInstallWarnings = false;
let installErrors = '';
let claudeAnalysis = '';
let installFixes = [];

try {
  const installResults = $('Parse Install Results').first().json;
  hasInstallErrors = installResults.hasErrors || false;
  hasInstallWarnings = installResults.hasWarnings || false;

  // Capture dependency errors/warnings even if install succeeded
  if (hasInstallErrors || hasInstallWarnings) {
    installErrors = installResults.dependencyErrors || installResults.fullOutput || '';

    // Only try to get Claude fixes if Claude was actually run (hasErrors = true)
    if (hasInstallErrors) {
      try {
        const claudeResponse = $('Parse Claude Response').first().json;
        claudeAnalysis = claudeResponse.claudeAnalysis || 'No analysis available';
        installFixes = claudeResponse.fixes || [];
      } catch (e) {
        claudeAnalysis = 'Claude analysis not run (warnings only, no critical errors)';
      }
    } else {
      // Just warnings, no Claude fixes needed
      claudeAnalysis = 'npm install succeeded with warnings. No fixes applied.';
    }
  }
} catch (e) {
  hasInstallErrors = false;
  hasInstallWarnings = false;
}

// Build run ID from branch name
const runId = branchName.replace('test-deps-update_', '');

// Get updates array - handle both 'updates' and 'upgrades' field names
let updatesArray = [];
if (updateInfo.updates && Array.isArray(updateInfo.updates)) {
  updatesArray = updateInfo.updates;
} else if (updateInfo.upgrades && Array.isArray(updateInfo.upgrades)) {
  updatesArray = updateInfo.upgrades;
}

// Build confluence data
const confluenceData = {
  runId: runId,
  branchName: branchName,
  projectPath: updateInfo.projectPath || '/Users/pato/github/ionutz0912/angular-test-project',
  totalUpdates: updateInfo.totalUpdates || 0,
  updates: updatesArray.map(u => ({
    name: u.name,
    from: u.from,
    to: u.to
  })),
  hasInstallErrors: hasInstallErrors || hasInstallWarnings,  // Document if either exists
  installErrors: installErrors,
  claudeAnalysis: claudeAnalysis,
  installFixes: installFixes,
  testPassed: testResults.testPassed || false,
  buildPassed: testResults.buildPassed || false,
  prUrl: prResponse.prUrl || '',
  prNumber: prResponse.prNumber || ''
};

return {
  json: confluenceData
};

const output = $input.first().json.stdout;

try {
  const data = JSON.parse(output);

  return {
    json: {
      success: data.success || false,
      pageId: data.page ? data.page.id : null,
      pageUrl: data.page ? data.page.url : null,
      pageTitle: data.page ? data.page.title : null,
      error: data.error || null,
      timestamp: data.timestamp || new Date().toISOString()
    }
  };
} catch (e) {
  return {
    json: {
      success: false,
      error: 'Failed to parse Confluence response',
      rawOutput: output
    }
  };
}
